    bool ok = *GetActive(0.0f, 1.0f, e, 4) == 20;        // clamped to 1 -> [1,3)
    ok = ok && *GetActive(2.4f, 1.0f, e, 4) == 20;       // 2 -> [1,3)
    ok = ok && *GetActive(2.6f, 1.0f, e, 4) == 30;       // 3 -> [3,6)
    ok = ok && *GetActive(9.0f, 1.0f, e, 4) == 40;       // 9 -> [6,10)
